select public.test_denied($q$select public.sync_workout_library(4, '{"version":4,"revision":0,"active":null,"history":[],"routines":[{"id":"r","name":"Plan","unit":"lb","exercises":[{"id":"re","name":"Row","targetWeight":null}]}]}')$q$, 'null routine target weight');
select public.test_denied($q$select public.sync_workout_library(4, '{"version":4,"revision":0,"active":null,"history":[],"routines":[{"id":"r","name":"Plan","unit":"lb","note":"n","exercises":[{"id":"re","name":"Row"}]}]}')$q$, 'note on routine');
select public.test_denied($q$select public.sync_workout_library(4, '{"version":3,"revision":0,"active":{"id":"w","name":"W","unit":"kg","startedAt":1,"finishedAt":null,"exercises":[{"id":"e","name":"Bench","sets":[]}],"note":"n"},"history":[]}')$q$, 'note rejected in schema3');
