select public.test_assert((select (data->'active'->'exercises'->0->'sets'->0->>'rpe')::numeric=8.5 and data->'active'->'exercises'->1->>'superset'='g1' and data->'active'->'exercises'->1->'bodyweight'='true'::jsonb and (data->'active'->'exercises'->1->'sets'->0->>'weight')::numeric=-20 and data->'routines'->0->'exercises'->1->>'superset'='p' from public.workout_libraries where user_id='11111111-1111-4111-8111-111111111111'), 'schema5 fields stored');
select public.test_denied($q$select public.sync_workout_library(7, '{"version":5,"revision":0,"active":{"id":"w","name":"W","unit":"kg","startedAt":1,"finishedAt":null,"exercises":[{"id":"a","name":"Ex a","sets":[{"id":"s","reps":5,"weight":20,"rpe":0.5}]}]},"history":[]}')$q$, 'RPE below 1');
