select public.test_denied($q$select public.sync_workout_library(7, '{"version":4,"revision":0,"active":{"id":"w","name":"W","unit":"kg","startedAt":1,"finishedAt":null,"exercises":[{"id":"a","name":"Ex a","sets":[{"id":"s","reps":5,"weight":20}],"bodyweight":true}]},"history":[]}')$q$, 'bodyweight rejected in schema4');
select public.test_denied($q$select public.sync_workout_library(7, '{"version":3,"revision":0,"active":{"id":"w","name":"W","unit":"kg","startedAt":1,"finishedAt":null,"exercises":[]},"history":[],"routines":[{"id":"r","name":"P","unit":"kg","exercises":[{"id":"x","name":"Row","bodyweight":true}]}]}')$q$, 'routine bodyweight rejected in schema3');
select public.test_denied($q$select public.sync_workout_library(7, '{"version":4,"revision":0,"active":{"id":"w","name":"W","unit":"kg","startedAt":1,"finishedAt":null,"exercises":[]},"history":[],"goals":[{"id":"g","name":"Pull-up","unit":"kg","bodyweight":true,"weight":-1000,"reps":5,"createdAt":3}]}')$q$, 'goals rejected in schema4');
select public.test_denied($q$select public.sync_workout_library(7, '{"version":2,"revision":0,"active":{"id":"w","name":"W","unit":"kg","startedAt":1,"finishedAt":null,"exercises":[]},"history":[],"goals":[]}')$q$, 'goals rejected in schema2');
select public.test_denied($q$select public.sync_workout_library(7, (select jsonb_build_object('version',5,'revision',0,'active',null,'history','[]'::jsonb,'goals',jsonb_agg(jsonb_build_object('id','g'||i,'name','E'||i,'unit','kg','weight',1,'reps',1,'createdAt',1))) from generate_series(1,101) as i))$q$, '101 goals');
select public.test_assert((select revision=7 from public.workout_libraries where user_id='11111111-1111-4111-8111-111111111111'), 'invalid schema5 writes preserve latest revision');
select public.test_assert((public.sync_workout_library(7, (select jsonb_build_object('version',5,'revision',0,'active',null,'history','[]'::jsonb,'goals',jsonb_agg(jsonb_build_object('id','g'||i,'name','E'||i,'unit','kg','weight',1,'reps',1,'createdAt',1))) from generate_series(1,100) as i))->>'revision')::int=8, '100 goals accepted');
select public.test_assert((public.sync_workout_library(8, '{"version":4,"revision":0,"active":{"id":"w","name":"W","unit":"kg","startedAt":1,"finishedAt":null,"exercises":[{"id":"a","name":"Ex a","sets":[{"id":"s","reps":5,"weight":20,"kind":"warmup"}],"targetWeight":5}]},"history":[]}'::jsonb)->>'revision')::int=9, 'schema4 writes still accepted');
select public.test_denied($q$select public.sync_workout_library(9, '{"version":5,"revision":0,"active":null,"history":[],"routines":[{"id":"r","name":"Pull","unit":"kg","exercises":[{"id":"re","name":"Row","targetWeight":-20}]}]}')$q$, 'negative target weight on a non-bodyweight routine exercise');
select public.test_denied($q$select public.sync_workout_library(9, '{"version":5,"revision":0,"active":null,"history":[],"routines":[{"id":"r","name":"Pull","unit":"kg","exercises":[{"id":"re","name":"Pull-up","bodyweight":true,"targetWeight":-1001}]}]}')$q$, 'bodyweight target below -1000');
select public.test_assert((public.sync_workout_library(9, '{"version":5,"revision":0,"active":null,"history":[],"routines":[{"id":"r","name":"Pull","unit":"kg","exercises":[{"id":"re","name":"Pull-up","bodyweight":true,"targetWeight":-20}]}]}'::jsonb)->'data'->'routines'->0->'exercises'->0->>'targetWeight')::numeric=-20, 'assisted bodyweight target weight round trip');
reset role;
